CREATE TABLE IF NOT EXISTS admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shop_products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, category VARCHAR(80) NOT NULL, description TEXT, price INT UNSIGNED NOT NULL DEFAULT 0, sizes VARCHAR(160) DEFAULT 'S, M, L', stock INT UNSIGNED NOT NULL DEFAULT 0, image VARCHAR(160) NOT NULL, badge VARCHAR(40) DEFAULT 'NEW', featured TINYINT(1) NOT NULL DEFAULT 0, status TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shop_orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_name VARCHAR(160) NOT NULL, phone VARCHAR(40) NOT NULL, address TEXT, total INT UNSIGNED NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'demo_pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shop_order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NOT NULL, product_name VARCHAR(160) NOT NULL, price INT UNSIGNED NOT NULL, qty INT UNSIGNED NOT NULL, KEY order_idx(order_id), CONSTRAINT fk_order_item_order FOREIGN KEY(order_id) REFERENCES shop_orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cafe_categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, sort_order INT NOT NULL DEFAULT 0, status TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cafe_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, description TEXT, price INT UNSIGNED NOT NULL DEFAULT 0, barcode VARCHAR(60) NOT NULL UNIQUE, image VARCHAR(160) DEFAULT NULL, sort_order INT NOT NULL DEFAULT 0, status TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_cafe_category FOREIGN KEY(category_id) REFERENCES cafe_categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_demo_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, site_type VARCHAR(30) NOT NULL, title VARCHAR(160) NOT NULL, subtitle VARCHAR(255) DEFAULT NULL, image VARCHAR(160) DEFAULT NULL, price INT UNSIGNED NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY client_type_idx(site_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_demo_requests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, site_type VARCHAR(30) NOT NULL, name VARCHAR(160) NOT NULL, phone VARCHAR(40) NOT NULL, service VARCHAR(160) DEFAULT NULL, status VARCHAR(30) NOT NULL DEFAULT 'new', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY client_request_type_idx(site_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
